/**
 * @file    font16.h
 * @brief   16x16 CJK bitmap font (generated by tools/gen_font.py from
 *          Noto Sans CJK SC, embedded as font16.bin via EMBED_FILES).
 *
 *          Binary format (see tools/gen_font.py):
 *            header:  "HZ16" (4B) + glyph count (uint16 LE)
 *            entries: count x [codepoint (uint16 LE) + 32B bitmap]
 *            bitmap:  16 columns x 2 bytes, column-major;
 *                     low byte = rows 0..7, high byte = rows 8..15,
 *                     bit 0 = topmost row of that byte.
 */
#ifndef FONT16_H
#define FONT16_H

#include <stdint.h>

/**
 * @brief Decode one UTF-8 code point and advance *p past its bytes.
 *        Invalid sequences yield U+FFFD and advance one byte.
 */
uint32_t font16_utf8_next(const char **p);

/**
 * @brief Look up a 16x16 glyph by Unicode code point (binary search).
 * @return pointer to the 32-byte column bitmap, or NULL if not in the table.
 */
const uint8_t *font16_lookup(uint32_t cp);

#endif /* FONT16_H */
